package cully

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// MigrateProjectIntegration removes unchanged files generated by older setup
// versions, only in the explicitly selected project. It never follows symlinks
// or removes custom instructions, skills, commands, or nonempty directories.
func MigrateProjectIntegration(dir string, w io.Writer) error {
	root, err := filepath.Abs(dir)
	if err != nil {
		return err
	}
	info, err := os.Lstat(root)
	if err != nil {
		return err
	}
	if !info.IsDir() {
		return fmt.Errorf("migration project must be a directory, not a symlink or file: %s", root)
	}
	files := []struct {
		path, content string
		section       bool
	}{
		{filepath.Join(root, "AGENTS.md"), legacyCodexAgentInstructions(), true},
		{sharedSkillPath(root, "cully"), cullySkill(), false},
		{filepath.Join(root, ".cursor", "commands", "cully.md"), cursorCullyCommand, false},
	}
	for _, file := range files {
		if err := advisorLocalPath(root, file.path); err != nil {
			fmt.Fprintf(w, "Preserved unsafe or linked project path: %s\n", file.path)
			continue
		}
		info, err := os.Lstat(file.path)
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return err
		}
		if !info.Mode().IsRegular() {
			fmt.Fprintf(w, "Preserved nonregular project file: %s\n", file.path)
			continue
		}
		b, err := os.ReadFile(file.path)
		if err != nil {
			return err
		}
		text, remaining := string(b), ""
		if file.section {
			start, end := managedStart("codex"), managedEnd("codex")
			s := strings.Index(text, start)
			if s < 0 {
				continue
			}
			e := strings.Index(text[s+len(start):], end)
			if e < 0 {
				fmt.Fprintf(w, "Preserved modified project instructions: %s\n", file.path)
				continue
			}
			e += s + len(start)
			if strings.TrimSpace(text[s+len(start):e]) != strings.TrimSpace(file.content) {
				fmt.Fprintf(w, "Preserved modified project instructions: %s\n", file.path)
				continue
			}
			remaining = text[:s] + text[e+len(end):]
		} else if strings.TrimSpace(text) != strings.TrimSpace(file.content) {
			fmt.Fprintf(w, "Preserved modified project file: %s\n", file.path)
			continue
		}
		if strings.TrimSpace(remaining) == "" {
			err = os.Remove(file.path)
		} else {
			err = os.WriteFile(file.path, []byte(remaining), info.Mode().Perm())
		}
		if err != nil {
			return err
		}
		fmt.Fprintf(w, "Removed legacy Cully project integration: %s\n", file.path)
		// os.Remove only succeeds for empty directories; unrelated files stay.
		for parent := filepath.Dir(file.path); parent != root; parent = filepath.Dir(parent) {
			if err := os.Remove(parent); err != nil {
				break
			}
		}
	}
	return nil
}
